use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)] pub enum TransferDirection { Upload, Download }
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)] pub enum TransferStatus { Queued, Active, Done, Failed(String), Cancelled }
#[derive(Debug, Clone, Serialize, Deserialize)] pub struct TransferJob { pub id:u64, pub direction:TransferDirection, pub source:String, pub destination:String, pub progress:u8, pub status:TransferStatus }
#[derive(Debug, Default, Clone)] pub struct TransferQueue { pub jobs: Vec<TransferJob>, next_id:u64 }
impl TransferQueue { pub fn enqueue(&mut self, direction:TransferDirection, source:String, destination:String)->u64{ self.next_id+=1; let id=self.next_id; self.jobs.push(TransferJob{id,direction,source,destination,progress:0,status:TransferStatus::Queued}); id } pub fn start_next(&mut self){ if let Some(j)=self.jobs.iter_mut().find(|j|j.status==TransferStatus::Queued){ j.status=TransferStatus::Active; } } pub fn complete(&mut self,id:u64){ if let Some(j)=self.jobs.iter_mut().find(|j|j.id==id){ j.progress=100; j.status=TransferStatus::Done; } } pub fn fail(&mut self,id:u64,msg:String){ if let Some(j)=self.jobs.iter_mut().find(|j|j.id==id){ j.status=TransferStatus::Failed(msg); } } pub fn active_count(&self)->usize{ self.jobs.iter().filter(|j|matches!(j.status,TransferStatus::Queued|TransferStatus::Active)).count() } }
#[cfg(test)] mod tests { use super::*; #[test] fn transfer_queue_state_transitions(){ let mut q=TransferQueue::default(); let id=q.enqueue(TransferDirection::Upload,"a".into(),"b".into()); assert_eq!(q.active_count(),1); q.start_next(); assert_eq!(q.jobs[0].status,TransferStatus::Active); q.complete(id); assert_eq!(q.jobs[0].status,TransferStatus::Done); assert_eq!(q.active_count(),0); } }
